[InitializeOnLoad]static class Level103VisualCheck{
 const string Key="Spark103Visual";static Level103VisualCheck(){EditorApplication.update+=Poll;EditorApplication.playModeStateChanged+=State;}
 static void Poll(){if(!File.Exists("Logs/SparkLevel103Visual.request")||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;File.Delete("Logs/SparkLevel103Visual.request");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
 static async void State(PlayModeStateChange s){if(!SessionState.GetBool(Key,false))return;if(s==PlayModeStateChange.EnteredEditMode){SessionState.EraseBool(Key);return;}if(s!=PlayModeStateChange.EnteredPlayMode)return;var log=Debug.unityLogger.filterLogType;Debug.unityLogger.filterLogType=LogType.Error;Application.runInBackground=true;try{
