 await Task.Delay(1000);b.BoardView();await Task.Delay(700);var canvas=b.GetComponentInChildren<Canvas>(true);var corners=new Vector3[4];((RectTransform)canvas.transform).GetWorldCorners(corners);report+="Canvas active="+canvas.gameObject.activeInHierarchy+" enabled="+canvas.enabled+" layer="+canvas.gameObject.layer+" rect="+((RectTransform)canvas.transform).rect+" center="+Camera.main.WorldToViewportPoint(canvas.transform.position)+" corners="+string.Join(";",corners.Select(p=>Camera.main.WorldToViewportPoint(p).ToString()))+"\n";if(corners.Any(p=>{var v=Camera.main.WorldToViewportPoint(p);return v.z<=0||v.x<0||v.x>1||v.y<0||v.y>1;}))report+="FAIL controls outside viewport\n";else report+="PASS all four controls corners within viewport\n";File.WriteAllText("Logs/SparkLevel103Visual.txt",report);ScreenCapture.CaptureScreenshot("Logs/SparkLevel103Controls.png");await Task.Delay(300);
 }catch(Exception e){File.WriteAllText("Logs/SparkLevel103Visual.txt",e.ToString());}finally{Debug.unityLogger.filterLogType=log;EditorApplication.ExitPlaymode();}}
